	Y[30] = UltimateSmootherE(S6, 30);	// P30 alt
	Y[31] = UltimateSmootherE(S7, 30);	// P30 ramp
	Y[32] = use_ncl(S0, 20);	// NCL flat
	Y[33] = use_ncl(S1, 20);	// NCL s5
	Y[34] = use_ncl(S2, 20);	// NCL s10
	Y[35] = use_ncl(S3, 20);	// NCL s20
	Y[36] = use_ncl(S4, 20);	// NCL s40
