	Y[38] = use_ncl(S6, 20);	// NCL alt
	Y[39] = use_ncl(S7, 20);	// NCL ramp
	Y[40] = use_nca(S0, 20);	// NCA flat
	Y[41] = use_nca(S1, 20);	// NCA s5
	Y[42] = use_nca(S2, 20);	// NCA s10
	Y[43] = use_nca(S3, 20);	// NCA s20
	Y[44] = use_nca(S4, 20);	// NCA s40
	Y[45] = use_nca(S5, 20);	// NCA s100
