	Y[64] = use_ncx(S0, 20);	// NCX flat
	Y[65] = use_ncx(S1, 20);	// NCX s5
	Y[66] = use_ncx(S2, 20);	// NCX s10
	Y[67] = use_ncx(S3, 20);	// NCX s20
	Y[68] = use_ncx(S4, 20);	// NCX s40
	Y[69] = use_ncx(S5, 20);	// NCX s100
	Y[70] = use_ncx(S6, 20);	// NCX alt
	Y[71] = use_ncx(S7, 20);	// NCX ramp
	Y[72] = UltimateSmootherE(S0, 21);	// NC1 flat
	Y[73] = UltimateSmootherE(S1, 21);	// NC1 s5
	Y[74] = UltimateSmootherE(S2, 21);	// NC1 s10
	Y[75] = UltimateSmootherE(S3, 21);	// NC1 s20
	Y[76] = UltimateSmootherE(S4, 21);	// NC1 s40
	Y[77] = UltimateSmootherE(S5, 21);	// NC1 s100
	Y[78] = UltimateSmootherE(S6, 21);	// NC1 alt
	Y[79] = UltimateSmootherE(S7, 21);	// NC1 ramp
	Y[80] = use_nc2(S0, 20);	// NC2 flat
	Y[81] = use_nc2(S1, 20);	// NC2 s5
