		file_append(USE_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[16],Y[17],Y[18],Y[19],Y[20],Y[21],Y[22],Y[23]), 0);
